"""Collision detail/performance tradeoff review, keeping all visual bytes exact."""
import json
from pathlib import Path
from build import OUT

def main():
    renders=json.loads((OUT/'renders.json').read_text());data={}
    for item in json.loads((OUT/'variants.json').read_text()):
        path=Path(item['path']);r=json.loads(path.read_text());g=json.loads((path.parent/'geometry-verification.json').read_text());views={}
        for row in renders['views']:
            if row['variant']==r['variant']:views.setdefault(row['scope'],{}).setdefault(row['camera'],{})[row['stage']]=row['path']
        data[r['variant']]=dict(views=views,mesh=r['head_mesh_triangles_kept'],primitives=r['head_native_shapes'],preview=r['head_preview_triangles'],
            contacts=g['contact_grid'],fit=g['fit'],field=r['field_native_mesh_triangles'],counts=r['field_native_shape_counts'],
            reduction=100*(1-r['head_mesh_triangles_kept']/24474))
    html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground);line-height:1.45}p{margin:0 0 12px}.muted,small{color:var(--muted-foreground)}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}select{font:inherit;color:var(--foreground);background:var(--background);border:1px solid var(--border);border-radius:7px;padding:8px;max-width:100%}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.caption{font-size:13px;margin-bottom:5px}.imagebox{aspect-ratio:1;background:#c3d2e0;border-radius:8px;overflow:hidden}.imagebox img{display:block;width:100%;height:100%;object-fit:contain}table{border-collapse:collapse;width:100%;font-size:13px;margin:14px 0}td,th{text-align:left;padding:8px 5px;border-bottom:1px solid var(--border)}.note{padding:16px;margin:14px 0;background:var(--secondary);border-radius:var(--radius,10px)}.note p:last-child{margin-bottom:0}small{font-size:12px}
</style></head><body>
<p><strong>A much coarser head collider buys a larger reduction.</strong> The rear and internals become a small set of solid volumes. Visual appearance stays byte-identical.</p>
<div class="controls"><select id="variant" aria-label="Tradeoff"><option value="balanced">Balanced · suggested starting point</option><option value="lean">Lean · larger collision changes</option></select><select id="reference" aria-label="Reference"><option value="accepted">Previous collision</option><option value="visual">Approved visual appearance</option></select><select id="scope" aria-label="Scope"><option value="head">Head close-up</option><option value="whole-core">Whole Core</option></select><select id="camera" aria-label="Camera"><option value="front">Front</option><option value="back">Back</option><option value="left">Side</option><option value="right">Opposite side</option></select></div>
<div class="pair"><div><p class="caption" id="beforeLabel"></p><div class="imagebox"><img id="before" alt="Previous collision or unchanged visual"></div></div><div><p class="caption">Coarse collision candidate</p><div class="imagebox"><img id="after" alt="Grouped primitive collision envelope"></div></div></div>
<p id="variantNote" class="muted" style="font-size:13px;margin-top:9px"></p>
<table><thead><tr><th>Head per Core</th><th>Current vector proposal</th><th>Balanced</th><th>Lean</th></tr></thead><tbody><tr><td>Remaining mesh triangles</td><td>24,474</td><td>6,142</td><td>3,157</td></tr><tr><td>Head primitive leaves</td><td>11</td><td>23</td><td>22</td></tr><tr><td>Mesh reduction from current</td><td>—</td><td>74.9%</td><td>87.1%</td></tr></tbody></table>
<div class="note"><p><strong>I’d start with balanced.</strong> It gets most of the reduction and keeps the front collision triangles. The added volumes can block former through-paths. Lean replaces the slotted outer collider too, making it a solid casing.</p><p>Both retain the exact socket/nozzle meshes, bearing and marked interface frame. The new housing volumes leave the tested sleeve/nozzle approach channels empty. Small holes, rear pockets and mechanism detail are intentionally simplified.</p></div>
<p><strong>Measured contact tradeoff</strong> across the same 9,396 central-interface rays:</p>
<table><tbody><tr><td>First-hit distance changes over 25 mm</td><td id="shift25"></td></tr><tr><td>Hit/miss state changes</td><td id="state"></td></tr><tr><td>Largest common first-hit shift</td><td id="maxRay"></td></tr><tr><td>99th-percentile uncovered source distance</td><td id="p99"></td></tr></tbody></table>
<p class="muted"><small>The largest ray shifts reach roughly 179 mm when a small omitted part or a filled cavity changes which deeper surface is hit. This is deliberately approximate collision. The source-distance metric counts points inside new solids as covered; it does not hide the changed ray behavior.</small></p>
<p id="field" class="muted"></p>
<p class="muted"><small>These are proposed runtime representations, with no measured FPS or physics-time claim. Head parts are grouped only because this field head is currently rigid; future per-part motion must reject the group. The mixed/grouped primitive loader still needs implementing. Neither variant is installed or committed, and all previous candidates remain available.</small></p>
<script>const data=__DATA__,el=id=>document.getElementById(id);function show(){let name=el('variant').value,d=data[name],s=el('scope').value,c=el('camera').value,r=el('reference').value,v=d.views[s][c];el('before').src=v[r];el('after').src=v.candidate;el('beforeLabel').textContent=el('reference').selectedOptions[0].textContent;el('variantNote').textContent=name==='balanced'?'Blue: solid rear/body envelopes. Grey: exact retained collision, including the front mesh.':'Orange: lean solid casing and coarse rear mechanism. Grey: exact retained working-interface meshes.';let t=d.contacts;el('shift25').textContent=t.common_hit_shift_over_25mm.toLocaleString()+' / 9,396 ('+(100*t.common_hit_shift_over_25mm/t.probes).toFixed(1)+'%)';el('state').textContent=t.hit_state_changes.toLocaleString()+' / 9,396';el('maxRay').textContent=t.max_common_hit_shift_mm.toFixed(1)+' mm';el('p99').textContent=d.fit.source_uncovered_p99_mm.toFixed(1)+' mm';el('field').textContent='Whole-field native proposal: '+d.field.toLocaleString()+' mesh triangles + '+d.counts.cylinder+' cylinders + '+d.counts.box+' boxes + '+d.counts.convex_hull+' hulls. Native primitives are counted separately from the triangle preview.';}['variant','reference','scope','camera'].forEach(id=>el(id).onchange=show);show();console.log('Two coarse collision tradeoffs; 48 matched views');</script>
</body></html>'''
    (OUT/'gallery.html').write_text(html.replace('__DATA__',json.dumps(data)))

if __name__=='__main__':main()
